                        event.preventDefault();
                        props.onOpenTaskDetail(task.id);
                      }}","onClick={(event) => event.stopPropagation()}","onChange={(status) => props.onTaskStatusChange?.(task.id, status)}","disabled={props.statusChangeBusy || !props.onTaskStatusChange}","aria-label={row.hasChildren ? (isEnglishCopy ? `${row.expanded ? 'Collapse' : 'Expand'} ${task.title}` : `${row.expanded ? '收起' : '展开'}${task.title}`) : undefined}","disabled={!row.hasChildren}","onClick={(event) => {
